import{_ as t,o,c as n,ag as i}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Developers/Unique-replacement-process.md","filePath":"Developers/Unique-replacement-process.md"}'),a={name:"Developers/Unique-replacement-process.md"};function l(r,e,s,d,u,h){return o(),n("div",null,[...e[0]||(e[0]=[i("<p>Often we want to rephrase a Unique, or add a parameter in it that extends the use-case for that unique.</p><p>However, we need to allow modders some time to replace the old unique with the new one. This means there will be some overlap - usually around an &quot;entire minor version&quot;, which is 20 versions, which is ~2.5 months. During this time, both the old and new uniques need to work, and after this time, we should be able to find the old unique and properly kill it.</p><p>Here&#39;s how we go about it.</p><ul><li>Rename the old unique to <code>&quot;&lt;old-unique-name&gt;Old&quot;</code>, including uniques (shift+f6)</li><li>Create the new unique directly above the old one, using the old name</li><li>Wherever the old unique is used <strong>add in the new one</strong> rather than replacing it.</li><li>Add a @Deprecated annotation to the old unique, with the replacement text - this allows modders to auto-replace the old unique with the new one <ul><li>The deprecation level must be <code>DeprecationLevel.WARNING</code> - or do away with the deprecation level entirely since that&#39;s the default</li></ul></li></ul><p>After the time has passed, we will</p><ul><li>Move the old unique with the deprecation annotation to the bery top of &quot;deprecated and removed&quot; section, so it&#39;s sorted by recency</li><li>Remove all usages of the old unique from the code</li><li>Change the deprecation level to ERROR (which means we can&#39;t reintroduce usages)</li></ul>",6)])])}const m=t(a,[["render",l]]);export{p as __pageData,m as default};
